async createEvidencePackage(caseId, fileIds, ctx) {
    const files = await fileRepo.getImmutableMetadata(fileIds);
    const manifest = files.map(f => ({
        fileId: f.id,
        sha256: f.sha256,
        originalName: f.originalName,
        createdAt: f.createdAt,
        source: f.source,
    }));
    const manifestHash = sha256(canonicalJson(manifest));
     return evidencePackages.store({ caseId, manifest, manifestHash, createdBy: ctx.userId });
 }
